import ee, math, sys, traceback
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
lon, lat = 49.357405, 39.014501
aoi = ee.Geometry.Point([lon, lat]).buffer(4000)  # 4 km
dates = {
    'nov': '2022-11-19',
    'feb': '2023-02-13'
}

# Helpers
def s2_cloud_mask(img):
    qa = img.select('QA60')
    cloud = qa.bitwiseAnd(1 << 10).neq(0)
    cirrus = qa.bitwiseAnd(1 << 11).neq(0)
    mask = cloud.Or(cirrus).Not()
    return img.updateMask(mask)

def get_nearest_image(col, target_date):
    target = ee.Date(target_date)
    def add_diff(i):
        diff = ee.Number(i.date().millis().subtract(target.millis()).abs())
        return i.set('diff', diff)
    col2 = col.map(add_diff).sort('diff')
    return col2.first(), col2.size()

def analyze_s2(date_str, region):
    target = ee.Date(date_str)
    col = (ee.ImageCollection('COPERNICUS/S2_SR')
           .filterBounds(region)
           .filterDate(target.advance(-7,'day'), target.advance(7,'day'))
           .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80)))
    img, size = get_nearest_image(col, date_str)
    size_info = size.getInfo()
    if size_info == 0:
        return {'status':'C1'}
    img = ee.Image(img)
    img_masked = s2_cloud_mask(img)
    ndwi = img_masked.normalizedDifference(['B3','B8']).rename('ndwi')
    water = ndwi.gt(0.1).rename('water')
    land = water.Not().rename('land')

    # Counts and dates
    sel_date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd')
    total_px = img.select('B8').reduceRegion(
        reducer=ee.Reducer.count(), geometry=region, scale=1000, maxPixels=1e9
    ).get('B8')
    valid_px = water.reduceRegion(
        reducer=ee.Reducer.count(), geometry=region, scale=1000, maxPixels=1e9
    ).get('water')
    land_px = land.reduceRegion(
        reducer=ee.Reducer.sum(), geometry=region, scale=1000, maxPixels=1e9
    ).get('land')

    total_px, valid_px, land_px = total_px.getInfo(), valid_px.getInfo(), land_px.getInfo()
    sel_date = sel_date.getInfo()

    if valid_px is None or total_px is None:
        return {'status':'C3'}
    if valid_px == 0:
        return {'status':'C2', 'imgs': size_info, 'sensor':'S2', 'sel_date': sel_date}

    cloud_frac = None
    try:
        cloud_frac = 1.0 - (valid_px / total_px if total_px > 0 else None)
    except Exception:
        cloud_frac = None

    return {
        'status':'OK',
        'sensor':'S2',
        'imgs': size_info,
        'sel_date': sel_date,
        'valid_px': int(valid_px),
        'land_px': int(land_px) if land_px is not None else 0,
        'cloud_frac': float(cloud_frac) if cloud_frac is not None else None
    }

def analyze_s1(date_str, region):
    target = ee.Date(date_str)
    col = (ee.ImageCollection('COPERNICUS/S1_GRD')
           .filterBounds(region)
           .filterDate(target.advance(-10,'day'), target.advance(10,'day'))
           .filter(ee.Filter.eq('instrumentMode', 'IW'))
           .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV')))
    img, size = get_nearest_image(col, date_str)
    size_info = size.getInfo()
    if size_info == 0:
        return {'status':'C1'}
    img = ee.Image(img)
    vv = img.select('VV').updateMask(img.select('VV').gt(0))
    vv_db = vv.log10().multiply(10).focal_mean(radius=50, units='meters')
    water = vv_db.lt(-16).rename('water')
    land = water.Not().rename('land')

    sel_date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd').getInfo()
    valid_px = water.reduceRegion(
        reducer=ee.Reducer.count(), geometry=region, scale=1000, maxPixels=1e9
    ).get('water').getInfo()
    land_px = land.reduceRegion(
        reducer=ee.Reducer.sum(), geometry=region, scale=1000, maxPixels=1e9
    ).get('land').getInfo()

    if valid_px is None:
        return {'status':'C3'}
    if valid_px == 0:
        return {'status':'C2', 'imgs': size_info, 'sensor':'S1', 'sel_date': sel_date}

    return {
        'status':'OK',
        'sensor':'S1',
        'imgs': size_info,
        'sel_date': sel_date,
        'valid_px': int(valid_px),
        'land_px': int(land_px) if land_px is not None else 0,
        'cloud_frac': 0.0
    }

def analyze_date(date_key, date_str):
    # Try S2 first, then S1 if needed
    s2 = analyze_s2(date_str, aoi)
    if s2.get('status') == 'OK':
        return s2
    if s2.get('status') == 'C2' or s2.get('status') == 'C1':
        s1 = analyze_s1(date_str, aoi)
        if s1.get('status') == 'OK':
            return s1
        # if S1 fails too, propagate more specific status
        if s2.get('status') == 'C1' and s1.get('status') == 'C1':
            return {'status':'C1'}
        if s2.get('status') == 'C2' and s1.get('status') == 'C2':
            return {'status':'C2'}
        return s1  # return whatever S1 concluded (C1/C2/C3)
    if s2.get('status') == 'C3':
        return s2
    return s2

try:
    print("AOI: 39.014501,49.357405 r=4km | Water rules: S2 NDWI>0.1; S1 VV(dB)<-16")
    res_nov = analyze_date('nov', dates['nov'])
    res_feb = analyze_date('feb', dates['feb'])

    # Handle failure cases
    if res_nov.get('status') == 'C1' or res_feb.get('status') == 'C1':
        print("One or both dates: Empty collection after fallback.")
        print("C1")
        sys.exit(0)
    if res_nov.get('status') == 'C2' or res_feb.get('status') == 'C2':
        print("One or both dates: No valid pixels after masking/processing.")
        print("C2")
        sys.exit(0)
    if res_nov.get('status') == 'C3' or res_feb.get('status') == 'C3':
        print("Calculation failure (None/NaN encountered).")
        print("C3")
        sys.exit(0)

    # Prepare concise evidence lines
    def fmt_line(label, r):
        land_pct = (r['land_px'] / r['valid_px'] * 100.0) if r['valid_px'] > 0 else 0.0
        cloud_txt = "-" if r['cloud_frac'] is None else f"{r['cloud_frac']*100:.1f}%"
        return (f"{label} {r['sel_date']} [{r['sensor']}]: imgs={r['imgs']}, "
                f"valid_px={r['valid_px']}, land_px={r['land_px']} ({land_pct:.2f}%), "
                f"cloud_masked={cloud_txt}")

    print(fmt_line("NOV19", res_nov))
    print(fmt_line("FEB13", res_feb))

    # 5. Validation & Final Answer
    land_nov = res_nov['land_px'] if res_nov['land_px'] is not None else 0
    land_feb = res_feb['land_px'] if res_feb['land_px'] is not None else 0
    if (res_nov['valid_px'] is None) or (res_feb['valid_px'] is None):
        print("C3")
    else:
        appeared = (land_feb > 0) and (land_nov == 0)
        print("A" if appeared else "B")

except Exception as e:
    print("Error:", str(e))
    traceback.print_exc(limit=1)
    print("D")
